#include <memory.h>
#include <string.h>

// Assuming scoped_refptr is a reference-counted smart pointer similar to Chromium's implementation.
// Also assuming VideoFrame and VideoFrameLayout are defined elsewhere.

scoped_refptr<VideoFrame> CloneVideoFrameWithLayout(const VideoFrame* src_frame, const VideoFrameLayout& dst_layout) {
  // Validate the source frame pointer.
  if (!src_frame) {
    return nullptr;
  }

  // Check if the source frame is mappable.
  if (!src_frame->IsMappable()) {
    return nullptr;
  }

  // Check if the source format matches the destination layout format.
  if (src_frame->format() != dst_layout.format) {
    return nullptr;
  }

  // Create a new VideoFrame with the specified layout.
  scoped_refptr<VideoFrame> dst_frame = VideoFrame::Create(dst_layout);
  if (!dst_frame) {
    // Log an error if the destination frame creation fails.
    return nullptr;
  }

  // Copy the content from each plane of the source frame to the destination frame.
  for (size_t i = 0; i < src_frame->NumPlanes(); ++i) {
    const uint8_t* src_plane = src_frame->Data(i);
    uint8_t* dst_plane = dst_frame->Data(i);
    size_t plane_size = src_frame->RowBytes(i) * src_frame->height();

    // Ensure the copy is bounded by the plane size.
    if (plane_size > 0) {
      memcpy(dst_plane, src_plane, plane_size);
    }
  }

  return dst_frame;
}
